#include <functional>
#include <memory>
#include <string>
#include <system_error>

using Reply = int;

void send_request(int id, std::function<void(std::error_code, Reply)> done);
void report_failure(int id, const std::string& symbol, std::error_code error);
void report_reply(int id, const std::string& symbol, Reply reply);

// Defect in the by-reference version: `[&id, &symbol]` stores views of
// locals that die when submit_request returns. The event loop invokes the
// callback on a later turn, so both reads are use-after-scope -- and they
// are silent, because the closure itself is perfectly valid.
void submit_request(int id, std::string symbol) {
    send_request(id, [id, symbol = std::move(symbol)](std::error_code error,
                                                      Reply reply) {
        // No exception can cross the event-loop turn, so failure is an
        // explicit branch rather than a throw.
        if (error) {
            report_failure(id, symbol, error);
            return;
        }
        report_reply(id, symbol, reply);
    });
}

// When the state is large or several callbacks must share it, give it one
// owner whose lifetime covers the whole operation instead of copying it
// into each closure.
struct RequestState {
    int id;
    std::string symbol;
};

void submit_request_shared(int id, std::string symbol) {
    auto state = std::make_shared<RequestState>(id, std::move(symbol));
    send_request(state->id, [state](std::error_code error, Reply reply) {
        if (error) {
            report_failure(state->id, state->symbol, error);
            return;
        }
        report_reply(state->id, state->symbol, reply);
    });
}

#include <exception>
#include <future>
#include <iostream>
#include <stdexcept>
#include <thread>
#include <utility>
#include <vector>

double portfolio_risk(const std::vector<double>& positions) {
    if (positions.empty()) {
        throw std::runtime_error{"risk input unavailable"};
    }

    double sum = 0.0;
    for (double position : positions) {
        sum += position * position;
    }
    return sum;
}

void produce_risk(std::promise<double> promise,
                  std::vector<double> positions) {
    try {
        promise.set_value(portfolio_risk(positions));
    } catch (...) {
        // Exceptions do not propagate between threads on their own; the
        // shared state is the channel. current_exception() preserves the
        // dynamic type so the consumer's catch clauses still match.
        promise.set_exception(std::current_exception());
    }
}

void consume_risk(std::vector<double> positions) {
    std::promise<double> producer;
    std::future<double> result = producer.get_future();

    std::jthread worker{produce_risk, std::move(producer),
                        std::move(positions)};

    try {
        std::cout << result.get() << '\n';
    } catch (const std::runtime_error& error) {
        std::cout << error.what() << '\n';
    }
}

