class ThreadPool {
public:
    template<class F>
    auto submit(F&& function) -> std::future<std::invoke_result_t<F&>> {
        using Result = std::invoke_result_t<F&>;

        // The shared_ptr is an adaptation to the queue's element type:
        // std::function requires a copyable target and packaged_task is
        // move-only. Change the queue and the worker local to
        // std::move_only_function<void()> (C++23) and the lambda can capture
        // the packaged_task directly, removing this owner and its
        // control-block allocation.
        auto task = std::make_shared<std::packaged_task<Result()>>(
            std::forward<F>(function));

        std::future<Result> result = task->get_future();
        enqueue([task] { (*task)(); });
        return result;
    }

private:
    void enqueue(std::function<void()> work) {
        {
            std::lock_guard lock{mutex_};
            tasks_.push(std::move(work));
        }
        ready_.notify_one();
    }

    std::mutex mutex_;
    std::condition_variable ready_;
    std::queue<std::function<void()>> tasks_;
};

#include <condition_variable>
#include <mutex>
#include <stop_token>

std::mutex queue_mutex;
std::condition_variable ready;
std::condition_variable_any ready_any;
bool has_message = false;

void consume_message();

// A plain std::condition_variable has no stop-token overload, so the stop
// request has to be turned into a notification by hand.
void wait_for_message(std::stop_token stop) {
    // Registered *before* the wait. If the stop was already requested, the
    // callback runs inline during construction -- which is what closes the
    // window between testing the token and installing the hook. It may
    // therefore run on the requesting thread or on this one, so keep it
    // short.
    std::stop_callback wake_on_stop{stop, [] { ready.notify_all(); }};

    std::unique_lock lock{queue_mutex};
    ready.wait(lock, [&] {
        return has_message || stop.stop_requested();
    });

    if (stop.stop_requested()) {
        return;
    }
    consume_message();
}

// condition_variable_any packages the same pattern: the overload returns
// false when it stopped rather than when the predicate became true.
void wait_for_message_direct(std::stop_token stop) {
    std::unique_lock lock{queue_mutex};
    if (!ready_any.wait(lock, stop, [] { return has_message; })) {
        return;
    }
    consume_message();
}

#include <atomic>

enum class AsyncState {
    pending,
    completed,
    cancelled,
    timed_out
};

class CompletionRace {
public:
    bool complete() noexcept { return claim(AsyncState::completed); }
    bool cancel() noexcept { return claim(AsyncState::cancelled); }
    bool timeout() noexcept { return claim(AsyncState::timed_out); }

private:
    // Exactly one caller sees `true`. That caller publishes the result and
    // schedules the continuation once. A losing caller still unregisters its
    // own I/O, timer, or stop hook and drops its reference -- but it must
    // never publish a second result or resume the consumer again, because
    // the winner may already have destroyed the frame it would resume.
    bool claim(AsyncState terminal) noexcept {
        AsyncState expected = AsyncState::pending;
        return state_.compare_exchange_strong(
            expected, terminal,
            std::memory_order_acq_rel,
            std::memory_order_acquire);
    }

    std::atomic<AsyncState> state_{AsyncState::pending};
};

#include <coroutine>
#include <exception>
#include <optional>
#include <utility>

using Connection = int;
using Order = int;
using Confirmation = int;

template<class T>
class Task {
public:
    struct promise_type;
    using Handle = std::coroutine_handle<promise_type>;

    struct promise_type {
        std::optional<T> value;
        std::exception_ptr error;

        Task get_return_object() { return Task{Handle::from_promise(*this)}; }
        std::suspend_always initial_suspend() noexcept { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }
        void return_value(T result) { value.emplace(std::move(result)); }
        void unhandled_exception() noexcept { error = std::current_exception(); }
    };

    explicit Task(Handle handle) noexcept : handle_(handle) {}
    Task(const Task&) = delete;
    Task(Task&& other) noexcept : handle_(std::exchange(other.handle_, {})) {}
    ~Task() { if (handle_) handle_.destroy(); }

    bool await_ready() const noexcept { return false; }
    void await_suspend(std::coroutine_handle<>) noexcept {}
    T await_resume() { return std::move(*handle_.promise().value); }

private:
    Handle handle_;
};

struct AsyncGateway {
    Task<Connection> connect();
    Task<int> send(Connection connection, Order order);
    Task<Confirmation> confirm(Connection connection);
};

// Removes all three callback costs: control flow is visible in this body
// rather than owned by the event loop; a failure can propagate as an
// exception through the promise instead of an error parameter threaded
// through every continuation; and the three dependent steps are three
// statements, not three nested lambdas.
//
// The obligation it introduces is lifetime. `order` is a value parameter,
// so the frame owns it across every suspension. A reference parameter would
// stay a reference in the frame, and resuming after the caller's argument
// died would read a dangling object -- silently, because the stored
// reference is itself perfectly valid.
Task<Confirmation> submit_order(AsyncGateway& gateway, Order order) {
    Connection connection = co_await gateway.connect();
    co_await gateway.send(connection, order);
    co_return co_await gateway.confirm(connection);
}

#include <atomic>
#include <coroutine>

class Event {
public:
    class Awaiter {
    public:
        explicit Awaiter(Event& event) noexcept : event_(event) {}

        // Fast path: no suspension at all if the event already fired.
        bool await_ready() const noexcept {
            return event_.set_.load();
        }

        // Returning bool lets the awaiter cancel the suspension it just
        // asked for: `false` means "do not suspend after all, resume this
        // coroutine immediately". That is what closes the window between
        // await_ready() reading false and the handle being stored -- set()
        // could have run in between, and without the re-check the coroutine
        // would park with nobody left to wake it.
        bool await_suspend(std::coroutine_handle<> handle) noexcept {
            event_.waiter_ = handle;
            if (event_.set_.load()) {
                event_.waiter_ = {};
                return false;
            }
            return true;
        }

        void await_resume() const noexcept {}

    private:
        Event& event_;
    };

    Awaiter operator co_await() noexcept { return Awaiter{*this}; }

    void set() {
        set_.store(true);
        std::coroutine_handle<> handle = waiter_;
        if (handle) {
            waiter_ = {};  // cleared first: never resume the same frame twice
            handle.resume();
        }
    }

private:
    std::atomic<bool> set_{false};
    std::coroutine_handle<> waiter_{};
};

#include <coroutine>
#include <exception>
#include <iterator>
#include <utility>

// One coroutine means one frame, so iterating the whole sequence performs a
// single allocation (or none, if the compiler elides it) and nothing per
// element -- unlike materialising every result into a container.
template<class T>
class Generator {
public:
    struct promise_type {
        T current{};
        std::exception_ptr error;

        Generator get_return_object() {
            return Generator{
                std::coroutine_handle<promise_type>::from_promise(*this)};
        }
        std::suspend_always initial_suspend() noexcept { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }

        std::suspend_always yield_value(T value) {
            current = std::move(value);   // publish, then suspend
            return {};
        }

        void return_void() noexcept {}
        void unhandled_exception() { error = std::current_exception(); }
    };

    using Handle = std::coroutine_handle<promise_type>;

    explicit Generator(Handle handle) noexcept : handle_(handle) {}
    Generator(const Generator&) = delete;
    Generator& operator=(const Generator&) = delete;
    Generator(Generator&& other) noexcept
        : handle_(std::exchange(other.handle_, {})) {}
    ~Generator() { if (handle_) handle_.destroy(); }

    class Iterator {
    public:
        explicit Iterator(Handle handle) noexcept : handle_(handle) {}

        bool operator==(std::default_sentinel_t) const noexcept {
            return !handle_ || handle_.done();
        }

        Iterator& operator++() {
            handle_.resume();
            rethrow_if_failed();
            return *this;
        }

        const T& operator*() const noexcept {
            return handle_.promise().current;
        }

    private:
        void rethrow_if_failed() const {
            if (handle_.promise().error) {
                std::rethrow_exception(handle_.promise().error);
            }
        }

        Handle handle_;
    };

    Iterator begin() {
        if (handle_) {
            handle_.resume();  // run up to the first co_yield
            if (handle_.promise().error) {
                std::rethrow_exception(handle_.promise().error);
            }
        }
        return Iterator{handle_};
    }

    std::default_sentinel_t end() const noexcept { return {}; }

private:
    Handle handle_;
};

Generator<int> counted(int limit) {
    for (int i = 0; i < limit; ++i) {
        co_yield i;
    }
}
